  "summary": "The code contains a critical SQL injection vulnerability, hardcoded configurations, and poor architectural separation. Overall health is poor; the refactored code introduces dependency injection, environment-based configuration, and parameterized queries to mitigate these risks.",
  "fixed_code": "const express = require('express');\nconst app = express();\nconst db = require('./db'); // Assuming db client is exported here\n\n/** \n * @param {import('express').Request} req \n * @param {import('express').Response} res \n */\nconst getUser = (req, res) => {\n    const { username } = req.query;\n    if (!username || typeof username !== 'string' || username.length > 50) {\n        return res.status(400).send('Invalid username');\n    }\n    db.query('SELECT * FROM users WHERE username = ? LIMIT 1', [username], (err, results) => {\n        if (err) {\n            return res.status(500).send('Database error');\n        }\n        res.json(results);\n    });\n};\n\napp.get('/user', getUser);\n\nconst PORT = process.env.PORT || 3000;\napp.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
